  ('fablhansl', 'Fablhansl', '', '', '', '', 'Fabelhansl', '[{"kategorie": "wörtlich", "text": "\"Fabelhans\" (\"jemand, der selbsterfundene Geschichten erzählt\", Determinativkompositum aus \"Fabel\"=\"Fantasiegeschichte\" und \"Hansl\"=\"Kerl\")"}, {"kategorie": "historisch", "text": "Beiname von \"Abraham a Santa Clara\" (barocker Prediger und Schriftsteller des 17. Jahrhunderts, bekannt für seine satirischen und volkstümlichen Predigten)"}, {"kategorie": "fig.", "text": "Geschichtenerzähler, Märchenerzähler, Märchenonkel (jemand, der gerne herumfabuliert)"}]'::jsonb, ''),
