  ('faabal', 'Faabal', '', '', '', 'Wiener Kartentipplerjargon', 'Farberl', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Farbensolo\" (Verkleinerungsform von \"Farbe\", abgeleitet vom mittelhochdeutschen \"varwe\"=\"Farbe\")"}, {"kategorie": "Kartenspielerjargon", "text": "Farbensolo beim Tarock-Zwanzigerrufen (ein Spieler [der Rufer] spielt gegen die anderen drei und muss mindestens 45 Punkte erzielen. Anstelle der Tarock zählen bei diesem Spiel die Farbkarten als Trumpfkarten. Der Rufer muss mindestens fünf Farbkarten haben, um ein Farbensolo rufen zu können)"}, {"kategorie": "", "text": "Farbensolo-Dreier im Tarock-Königrufen (beim Farben-Solo-Dreier ist die Stichkraft der Tarock gegenüber den Farben aufgehoben, sie sind einfach die fünfte Farbe. Der Spieler spielt allein gegen die anderen drei. Spielziel ist das Spiel, also mindestens 35 Punkte und zwei Blatt. Das Spiel zählt zehn Punkte)"}]'::jsonb, 'A Faabal is augsogd!'),
  ('foab', 'Foab', '', '', '', '', 'Farbe', '[{"kategorie": "wörtlich", "text": "\"Farbe\" (vom mittelhochdeutschen \"varwe\"=\"Farbe\")"}, {"kategorie": "", "text": "Gesichtsfarbe, Teint"}, {"kategorie": "Kartenspielerjargon", "text": "Spielkartenfarbe"}]'::jsonb, ''),
  ('fuazwuazn', 'Fuazwuazn', '', '', '', '', 'Furzwurzen', '[{"kategorie": "wörtlich", "text": "\"Furzwurze\" bzw. \"Wurzel, die Darmblähungen auslöst\" (=Determinativkompositum aus \"Furz\"=\"[[Schas]]\" und [[Wurzen]]=\"große Wurzel\")"}, {"kategorie": "scherzhaft für", "text": "Rettich, [[Radi]] (dicke, rübenförmige, scharf schmeckende Wurzel)"}]'::jsonb, ''),
  ('fasch', 'Fasch', 'die', '', '', '', 'Fasch', '[{"kategorie": "wörtlich", "text": "\"Füllung\" (vom französischen \"farce\"=\"Füllung\", abgeleitet vom lateinischen \"farcire\"=\"hineinstopfen\")"}, {"kategorie": "Küchenjargon", "text": "\"Farce\" (fein zerkleinerte und gewürzte Mischung aus Fleisch, Fisch oder Gemüse, die als Füllung für Gerichte wie Terrinen, Pasteten und Klöße verwendet wird)"}]'::jsonb, ''),
  ('faschnkind', 'Faschnkind', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Faschenkind', '[{"kategorie": "wörtlich", "text": "\"in eine Fasche gewickeltes Kind\" (Determinativkompositum aus [[Fasche]]=\"Binde\" und \"Kind\"=[[Baby]])"}, {"kategorie": "hist.", "text": "Wickelkind, \"Baby im Wickelband\" (ein Kleinkind, das mit Binden oder Leinentüchern fest umwickelt wurde, um es ruhig zu halten und gerade wachsen zu lassen. Diese Wickeltechnik wurde im Volksglauben mit Körperkontrolle, Ordnung und Schutz verbunden. Faschenkinder waren in alten Bauernfamilien, Klöstern und Ammenhäusern üblich), Säugling, Neugeborenes, [[Butzerl]]"}]'::jsonb, 'I woa no a Faschnkind - wäu mei Uarli gsogd hod, dass a Kind oone Faschn vawochsd!'),
  ('faschee', 'faschee', '', '', '', '', 'faché', '[{"kategorie": "wörtlich", "text": "\"verärgert\" (vom französischen \"faché\"=\"verärgert\")"}, {"kategorie": "allg.", "text": "böse, sauer, verdrossen, fuchsig"}]'::jsonb, 'De is uandlich faschee!'),
  ('fasslbinda', 'Fasslbinda', '', '', '', '', 'Fasslbinder', '[{"kategorie": "wörtlich", "text": "\"Fassbinder\" (Determinativkompositum aus \"Fass\"=\"großer, zylindrischer Behälter aus Holz oder Metall\" und \"Binder\"=\"Küfer\")"}, {"kategorie": "allg., Berufsbezeichnung", "text": "Böttcher, Küfer, Fassküfer"}]'::jsonb, ''),
  ('fasslficka', 'Fasslficka', '', '', '', '', 'Fasslficker', '[{"kategorie": "wörtlich", "text": "\"Fassficker\" (Determinativkompositum aus \"Fass\"=\"großer, zylindrischer Behälter aus Holz oder Metall\" und \"Ficker\"=[[Puderant]])"}, {"kategorie": "scherzhaft für", "text": "\"Pfundsweiber-Puderant\", \"Vollweib-Bumser\", \"Fettkugel-Ficker\" (Sexualpartner von einem [[schweren Trumm]] [Deutschland: \"Sexcualpartner einer Wuchtbrumme\"])"}]'::jsonb, ''),
  ('fasslreida', 'Fasslreida', '', '', '', '', 'Fasslreiter', '[{"kategorie": "wörtlich", "text": "\"Fassreiter\" (Determinativkompositum aus \"Fass\"=\"großer, zylindrischer Behälter aus Holz oder Metall\" und \"Reiter\"=\"Reitersmann\")"}, {"kategorie": "scherzhaft für", "text": "\"O-beiniger Mensch\", \"Mensch mit O-Beinen vom vielen Fasssitzen\", [[O-Haxlerter]], [[Kniaradlada]] (Person mit nach außen gewinkelten Beinen wie bei einem Radfahrer)"}]'::jsonb, ''),
  ('fasslrutschn', 'Fasslrutschn', '', '', '', '', 'Fasslrutschen', '[{"kategorie": "wörtlich", "text": "\"Fassrutschen\" (Determinativkompositum aus \"Fass\"=\"großer, zylindrischer Behälter aus Holz oder Metall\" und \"rutschen\"=\"hinabgleiten\")"}, {"kategorie": "", "text": "traditionelles Fasslrutschen zu [[Leopoldi]] am 15. November im Binderstadl im Chorherrenstift Klosterneuburg nahe Wien (zur Feier des [[Heiligen]] Leopold dürfen Gäste einmal im Jahr über ein 1.000-Eimer-Riesenfass hinabrutschen, welches  fünf Meter lang und vier Meter hoch ist, eine Füllmenge von 56.000 Liter hat und im Jahre 1704 angefertigt wurde)"}]'::jsonb, ''),
  ('leopoidi', 'Leopoidi', '', '', '', '', 'Leopoldi', '[{"kategorie": "wörtlich", "text": "\"Feiertag im Gedenken an den [[Heiligen]] Leopold\" (Landespatron von Wien und Niederösterreich, Gründer des Chorherrenstifts Klosterneuburg)"}, {"kategorie": "allg.", "text": "schulfreier Tag in Wien und Niederösterreich (15. November, Sterbetag des [[Heiligen]] Leopold)"}]'::jsonb, ''),
  ('koinbeag', 'Koinbeag', '', '', '', '', 'Kahlenberg', '[{"kategorie": "wörtlich", "text": "Berg im 19. Wiener Gemeindebezirk ([[Döbling]]) an der Grenze zu Klosterneuburg (484m hoch, zum Wienerwald gehörig und damit Teil des Alpenhauptkamms)"}, {"kategorie": "", "text": "bekanntester Aussichtspunkt auf Wien (vom Kahlenberg hat man Aussicht auf ganz Wien und bei guter Sicht bis zu den Kleinen Karpaten in der Slowakei bzw. zum Schneeberg in den Steirisch-niederösterreichische Kalkalpen. Sein Gipfel überragt das [[Wiener]] Becken um etwa 320 m. Von der Stefaniewarte, die sich auf dem höchsten Punkt des Berges befindet, kann man auch auf Teile Niederösterreichs sehen)"}, {"kategorie": "", "text": "traditionelles Sonntagsausflugsziel der Wiener und Sehenswürdigkeit Wiens (bei der [[zweiten]] Türkenbelagerung 1683 wurde die Stadt von hier aus vom Entsatzheer befreit, woran die Josefskirche erinnert)"}]'::jsonb, ''),
  ('leopoidsbeag', 'Leopoidsbeag', '', '', '', '', 'Leopoldsberg', '[{"kategorie": "wörtlich", "text": "zur Donau abfallender Berg im 19. Wiener Gemeindebezirk ([[Döbling]]) an der Grenze zu Klosterneuburg (425m hoch, zum Wienerwald gehörig und damit Teil des Alpenhautpkamms)"}, {"kategorie": "", "text": "\"die Burg am Leopoldsberg\" (früher als „Burg Ka(h)lenberg“ bezeichnet,  war eine landesfürstliche Burg der Babenberger und später der Habsburger. Die Burg und das innere Burgareal mit der darauf befindlichen Kirche am Leopoldsberg [Kirche zum Hl. Leopold auf dem Leopoldsberg, auch „Leopoldikapelle“] ist seit Juni 2018 öffentlich zugänglich. Erst nach der Erbauung der Leopoldskirche 1679 beziehungsweise 1693 bürgerte sich der Name Leopoldsberg ein; der Name [[Kahlenberg]] ging auf den benachbarten Berg über [ursprünglich Schweins- oder Sauberg, ab 1629 Josefsberg])"}]'::jsonb, ''),
  ('fazku', 'Fazku', '', '', '', '', 'die Fatzku', '[{"kategorie": "wörtlich", "text": "\"Ohrfeige\" (eigtl. Akkusativ des tschechischen Worts \"facka\"=\"Ohrfeige\")"}, {"kategorie": "", "text": "[[Watschen]], [[Dachtel]], [[Fotzn]], [[Tschinöön]]"}]'::jsonb, ''),
  ('fotoeoe', 'Fotöö', '', '', '', '', 'Fauteuil', '[{"kategorie": "wörtlich", "text": "\"Lehnsessel\" (vom altfranzösischen \"faldestueuil\"=\"Faltsessel\")"}, {"kategorie": "allg.", "text": "Polstersessel, Armstuhl, Clubsessel (bequemer Polstersessel mit Armlehnen)"}]'::jsonb, ''),
  ('margaretnschdrossn', 'Margaretnschdrossn', '', '', '', '', 'Margaretenstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Geschäftsstraße im 4. und 5. Wiener Gemeindebezirk ([[Wieden]] und [[Margareten]]), sowie eine der Hauptstraßen im Bezirk Margareten"}, {"kategorie": "", "text": "Die Margaretenstraße ist eine der ältesten Straßen in diesem Teil Wiens und war ursprünglich eine Verbindung vom Stadtkern zu den damals ländlichen Gebieten im Südwesten. Ihr Name leitet sich vom Bezirk Margareten ab, der nach der Heiligen Margareta benannt ist"}, {"kategorie": "", "text": "Die Margaretenstraße ist geprägt von einer Mischung aus historischen Gebäuden und modernen Bauten. Viele der Häuser stammen aus der Gründerzeit des 19. Jahrhunderts und sind typische Wiener Zinshäuser mit dekorativen Fassaden"}, {"kategorie": "", "text": "In den letzten Jahrzehnten wurden einige historische Gebäude modernisiert, und es entstanden auch neue Wohn- und Geschäftsbauten, die der Straße ein modernes und urbanes Flair verleihen."}]'::jsonb, ''),
  ('gumpnduafaschdrossn', 'Gumpnduafaschdrossn', '', '', '', '', 'Gumpendorfer Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Einkaufsstraße im 6. Wiener Gemeindebezirk ([[Mariahilf]]), die sich bis in den 15. Bezirk ([[Rudolfsheim-Fünfhaus]]) erstreckt"}, {"kategorie": "", "text": "Sie beginnt im Osten im 6. Bezirk ([[Mariahilf]]), nahe dem [[Naschmarkt]] und der [[Mariahilfer]] Straße, und verläuft in westlicher Richtung bis in den 15. Bezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Sie gehört zu den ältesten Straßenverbindungen Wiens und hat sich im Laufe der Jahrhunderte zu einer lebendigen und vielfältigen Straße entwickelt, die sowohl durch ihre historische Bedeutung als auch durch ihre kulturelle und kommerzielle Vielfalt geprägt ist"}, {"kategorie": "", "text": "Die Gumpendorfer Straße zeichnet sich durch eine abwechslungsreiche Architektur aus, die von historischen Bauten aus der Gründerzeit bis hin zu modernen Gebäuden reicht. Besonders hervorzuheben ist die Architektur des 19. und frühen 20. Jahrhunderts, die entlang der Straße präsent ist. Diese Gebäude verleihen der Straße ihren charakteristischen Wiener Charme."}]'::jsonb, ''),
  ('favoritn', 'Favoritn', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Favoriten', '[{"kategorie": "wörtlich", "text": "\"Wien-Favoriten\""}, {"kategorie": "", "text": "\"der zehnte [[Hieb]]\" (10. Wiener Gemeindebezirk\")"}, {"kategorie": "", "text": "Favoriten ist benannt nach dem ehemaligen Lustschloss [[Favorita]], das von [[Kaiser]] Ferdinand III. als Sommersitz des Hofs auf der [[Wieden]], am Platz des heutigen [[Theresianums]], errichtet wurde und von wo die heutige [[Favoritenstraße]] zum [[Favoritentor]] des [[Linienwalls]] führte, d.h. Favoriten liegt heute dort, wo einst - außerhalb des Linienwalls - \"die Siedlung vor der Favoriten-Linie\" entstanden ist"}, {"kategorie": "", "text": "Favoriten wurde 1874 aus den damals südlich der Stadt gelegenen Vororten und ländlichen Gebieten gegründet. Der Bezirk hat eine lange industrielle Tradition, die sich in vielen ehemaligen Fabriken und Industriebauten widerspiegelt"}, {"kategorie": "", "text": "Ursprünglich war das Gebiet des heutigen Favoriten einerseits ländlich und andererseits duch die damalige Ziegelindustrie geprägt (viele „Ziegelböhm:innen“ [[[Ziaglbeem]]] aus Böhmen und Mähren als Arbeiter im 19. Jh.). Im 20. Jahrhunder erfolgte der Ausbau Favoritens zum Arbeiter- und Industriestandort mit vielen Wohnsiedlungen im Stil des à„Roten Wien“ ([[Gemeindebauten]])"}, {"kategorie": "", "text": "Heute ist Favoriten ein dynamischer, wachsender Bezirk im sozialen Wandel. Mit ca. 215.000 Menschen ist Favoriten der einwohnerstärkste Bezirk Wiens mit einem hohen Maß an Zuwanderung (über 40 % mit Migrationshintergrund, v. a. Türkei, Ex-Jugoslawien, Syrien) und einer Mischung aus traditionellem Wiener Proletariat, zugewanderten Communities und jungen Familien wie auch älteren Bewohnern"}, {"kategorie": "", "text": "Die bekannesten Grätzeln des Bezirks sind \"Alt-Favoriten\", das Sonnwendviertel, die [[Kreta]], [[Oberlaa]] und [[Unterlaa]]"}, {"kategorie": "", "text": "Trotz städtischer Dichte gibt es in Favoriten viele Grün- und Freizeitflächen, wie z.B. den [[Kurpark]] Oberlaa (einer der größten Parks Wiens), die [[Therme]] Wien (moderne Thermal- & Wellnessanlage), die [[Laudon-Wiese]] und das Erholungsgebiet [[Wienerberg]], sowie den [[Laaer]] Wald und den [[Böhmischen]] Prater (traditioneller Vergnügungspark mit Waldzugang)"}, {"kategorie": "", "text": "Favoriten ist ein vielfältiger, wachsender und multikultureller Stadtteil, der sich vom klassischen Arbeiterbezirk zum modernen Lebensraum mit großem Wohn-, Freizeit- und Entwicklungspotenzial gewandelt hat. Er vereint Geschichte, sozialen Wandel, grüne Erholungsräume, moderne Infrastruktur und ein kosmopolitisches Lebensgefühl – mitten im Süden Wiens"}]'::jsonb, ''),
  ('favoritnschdrossn', 'Favoritnschdrossn', '', '', '', '', 'Favoritenstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrs- und Einkaufsstraße, die aber auch eine historische Bedeutung für den 10. Wiener Gemeindebezirk ([[Favoriten]]) hat"}, {"kategorie": "", "text": "Sie war eine der ersten Straßen, die in dem Gebiet angelegt wurden, als Favoriten im 19. Jahrhundert entwickelt wurde"}, {"kategorie": "", "text": "Die Favoritenstraße ist heute eine der zentralen Lebensadern des 10. Bezirks in Wien. Sie verbindet den [[Hauptbahnhof]] mit den südlichen Teilen von Favoriten und spielt eine wichtige Rolle als Einkaufsstraße, Verkehrsweg und sozialer Treffpunkt. Die Mischung aus traditionellen Geschäften, modernen Einrichtungen und einer lebendigen Fußgängerzone ([[Favoritner Fußgängerzone]]) macht die Favoritenstraße zu einem bedeutenden Teil des städtischen Lebens in Favoriten und Wien insgesamt."}]'::jsonb, ''),
  ('westbaunhof', 'Westbaunhof', '', '', '', '', 'Westbahnhof', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Westbahnhof\" - einer der wichtigsten Bahnhöfe in Wien und ein zentraler Verkehrsknotenpunkt im Westen der Stadt"}, {"kategorie": "", "text": "Er befindet sich im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]) und dient als Endpunkt für mehrere nationale und internationale Bahnstrecken"}, {"kategorie": "", "text": "Der Westbahnhof ist nicht nur ein bedeutender Bahnhof, sondern auch ein Einkaufszentrum und ein historisches Wahrzeichen Wiens"}, {"kategorie": "", "text": "Er wurde ursprünglich 1858 eröffnet und war der Ausgangspunkt der Westbahn, einer der wichtigsten Eisenbahnstrecken Österreichs, die Wien mit Salzburg und weiter mit Deutschland verbindet"}, {"kategorie": "", "text": "Im Zweiten Weltkrieg wurde der Bahnhof schwer beschädigt und in den 1950er Jahren wieder aufgebaut. Das heutige Hauptgebäude im modernen Stil wurde 1951 eröffnet und gilt als ein Beispiel der Nachkriegsarchitektur"}, {"kategorie": "", "text": "Der Bahnhof wurde mehrfach modernisiert, zuletzt im Rahmen des Projekts \"BahnhofCity Wien West\", das 2011 abgeschlossen wurde. Im Zuge dieser Modernisierung wurden die Bahnhofsgebäude umfassend renoviert und mit einem Einkaufszentrum, Gastronomieangeboten und Büros ergänzt."}]'::jsonb, ''),
  ('hauptbaunhof', 'Hauptbaunhof', '', '', '', '', 'Hauptbahnhof', '[{"kategorie": "allg., kurz für", "text": "\"Wiener Hauptbahnhof\" - zentraler Bahnhof in Wien und einer der wichtigsten Verkehrsknotenpunkte in Österreich"}, {"kategorie": "", "text": "Er befindet sich im 10. Wiener Gemeindebezirk ([[Favoriten]]) in unmittelbarer Nähe zum [[Südtiroler]] Platz"}, {"kategorie": "", "text": "Der Wiener Hauptbahnhof wurde zwischen 2010 und 2014 auf dem Gelände des ehemaligen [[Südbahnhofs]] errichtet, der 2009 abgerissen wurde. Der Bahnhof verfügt über 12 Bahnsteige, die sowohl für den Fern- als auch für den Nahverkehr genutzt werden, sowie über eine Vielzahl von Geschäften, Restaurants und Serviceeinrichtungen. Die Dachkonstruktion des Bahnhofs ist markant und verleiht dem Gebäude eine einzigartige, futuristische Optik"}, {"kategorie": "", "text": "Der Bau des Hauptbahnhofs war der Ausgangspunkt für die Entwicklung eines neuen Stadtteils, dem [[Quartier]] Belvedere, das moderne Wohn- und Bürogebäude, Hotels, Einkaufszentren und Freizeiteinrichtungen umfasst. Dieses Viertel hat die Umgebung des Bahnhofs in ein lebendiges, urbanes Zentrum verwandelt."}]'::jsonb, ''),
  ('suedbaunhof', 'Südbaunhof', '', '', '', '', 'Südbahnhof', '[{"kategorie": "allg.", "text": "\"historischer Hauptbahnhof in Wien, der als zentraler Verkehrsknotenpunkt für den Süden und Osten Europas diente. Er wurde 1874 eröffnet und war bis zu seinem Abriss im Jahr 2010 in Betrieb\""}, {"kategorie": "", "text": "Der ursprüngliche Wiener Südbahnhof entstand durch den Zusammenschluss zweier Bahnhöfe: des Südbahnhofs und des Ostbahnhofs. Der Südbahnhof wurde ursprünglich als Endstation der Südbahnstrecke nach Triest und Venedig konzipiert, die Wien mit dem Mittelmeer verband. Der Ostbahnhof diente als Ausgangspunkt für Strecken in Richtung Ungarn und die Balkanregion. Diese beiden Bahnhöfe wurden schließlich zu einem großen Bahnhofskomplex zusammengefasst"}, {"kategorie": "", "text": "Nach dem Wiederaufbau in den 1950er Jahren präsentierte sich der Wiener Südbahnhof als modernes Bauwerk der Nachkriegsarchitektur"}, {"kategorie": "", "text": "Das Empfangsgebäude war ein großes, rechteckiges Bauwerk, das durch seine Glas- und Betonarchitektur auffiel. Es bot eine Vielzahl von Dienstleistungen, darunter Restaurants, Geschäfte und Reisebüros, und war ein wichtiger Anlaufpunkt für Reisende in Wien"}, {"kategorie": "", "text": "Der Wiener Südbahnhof wurde 2010 abgerissen, um Platz für den Bau des neuen [[Wiener]] Hauptbahnhofs zu schaffen. Der Hauptbahnhof, der 2014 offiziell eröffnet wurde, ersetzte den Südbahnhof als zentrales Eisenbahndrehkreuz der Stadt. Der neue Hauptbahnhof integriert die Funktionen des Südbahnhofs, des Westbahnhofs und anderer Bahnhöfe und bietet moderne Infrastruktur für den nationalen und internationalen Bahnverkehr."}]'::jsonb, ''),
  ('favorita', 'Favorita', '', '', '', '', 'Favorita', '[{"kategorie": "wörtlich", "text": "\"Lustschloss Favorita\" (vom lateinischen \"favor\"=\"Gunst\" bzw. \"Gefallen)"}, {"kategorie": "", "text": "historischer Sommersitz des Hofs auf der Wieden (am Platz des heutigen [[Theresianums]]), welcher von [[Kaiser]] Ferdinand III. bgründet wurde"}, {"kategorie": "", "text": "[[Neue Favorita]] (im Gegensatz zur [[Alten Favorita]], welche sich im [[Augarten]] befindet)"}]'::jsonb, ''),
  ('theresianum', 'Theresianum', '', '', '', '', 'Theresianum', '[{"kategorie": "wörtlich", "text": "\"Theresianische Akademie\" (benannt nach Kaiserin [[Maria]] Theresia, die - nach dem Verkauf des Jagdschlosses [[Favorita]] an den Jesuitenorden - dieses mit ihrer Stiftung wieder an sich nahm [nachdem die Mittel des Jesuitenordens für einen dort vorgesehenen Schulbetrieb nicht ausreichten] und an gleicher Stelle ein Gymnasium für Adelssöhne errichtete)"}, {"kategorie": "heute", "text": "öffentliches Gymnasium der Stiftung Theresianische Akademie für Burschen und Mädchen (mit Halb- bzw. Vollinternat)"}, {"kategorie": "", "text": "Sitz der Diplomatischen Akademie (untergebracht in einem Gebäudeteil der Theresianischen Akademie)"}]'::jsonb, ''),
  ('augoatnpalaeae', 'Augoatnpalää', '', '', '', '', 'Augartenpalais', '[{"kategorie": "wörtlich", "text": "\"Palais Augarten\""}, {"kategorie": "hist.", "text": "palaisähnlicher Prunkbau im Wiener [[Augarten]] (errichtet Ende des 17. Jh. nach einem Entwurf von Johann Fischer von Erlach, 1780 von Kaiser Josef II erworben. Bis in das 20. Jh. hinein wurde es von Mitgliedern des Kaiserhauses bzw. des Hofes bewohnt)"}, {"kategorie": "heute", "text": "Wohnsitz, Übungsstätte und Ausbildungsort (Gymnasium) der [[Wiener]] Sängerknaben"}]'::jsonb, ''),
  ('freiheanschdaund', 'Freiheanschdaund', '', '', '', '', 'Freiherrenstand', '[{"kategorie": "wörtlich", "text": "\"historischer Adelsstand des Heiligen Römischen Reiches, der in Österreich und dem Deutschen Reich bis 1919 fortbestand\""}, {"kategorie": "", "text": "\"Herrenstand\", der beim [[Freiherrn]] begann (im Gegensatz zum niedrigeren Ritterstand)"}, {"kategorie": "", "text": "Der Freiherr gehörte zum titulierten Adel wie auch Graf, Fürst und Herzog, im Gegensatz zum untitulierten Adel, der lediglich das Adelsprädikat „von“ im Namen trug."}]'::jsonb, ''),
  ('freihea', 'Freihea', '', '', '', '', 'Freiherr', '[{"kategorie": "wörtlich", "text": "\"historischer Adelstitel des Heiligen Römischen Reiches, der in Österreich und dem Deutschen Reich bis 1919 fortbestand\""}, {"kategorie": "", "text": "Mitglied des \"Herrenstands\", der beim \"Freiherrn\" begann (im Gegensatz zum niedrigeren Ritterstand)"}, {"kategorie": "", "text": "Der Freiherr gehörte zum titulierten Adel wie auch Graf, Fürst und Herzog, im Gegensatz zum untitulierten Adel, der lediglich das Adelsprädikat „von“ im Namen trug."}]'::jsonb, ''),
  ('rittastaund', 'Rittastaund', '', '', '', '', 'Ritterstand', '[{"kategorie": "wörtlich", "text": "historischer Adelsstand, der unterhalb des [[Freiherrenstandes]] angesiedelt war"}, {"kategorie": "hist.", "text": "Adelsstand, dessen Angehörige die Lehnsfähigkeit besitzen (Ritter waren ursprünglich berittene Krieger des Mittelalters, die durch besondere Tapferkeit oder Dienste für den Herrscher in den Ritterstand erhoben wurden. Sie hatten bestimmte Privilegien und Pflichten, darunter militärische Dienste und die Verwaltung von Lehen)"}]'::jsonb, ''),
  ('belvedea', 'Belvedea', '', '', '', '', 'Belvedere', '[{"kategorie": "wörtlich", "text": "\"Schloss Belvedere\" (vom italienischen \"bel vedere\"=\"schöne Aussicht\")"}, {"kategorie": "", "text": "Bedeutendes Kunstmuseum und ein herausragendes Beispiel barocker Architektur (erbaut von Johann Lucas von Hildebrandt (1668–1745) zwischen 1714 und 1723 für [[Prinz]] Eugen von Savoyen. Das Obere Belvedere und das Untere Belvedere - benannt aufgrund der Lage auf einem südlich der damaligen Stadt ansteigenden Hang - bilden mit der verbindenden Gartenanlage ein barockes Ensemble. Die beiden Schlossbauten beherbergen heute die Sammlungen des Belvederes (Österreichische Galerie Belvedere) und Räumlichkeiten für Wechselausstellungen)"}, {"kategorie": "", "text": "Ort der Unterzeichnung des [[Österreichischen]] Staatsvertrags (welcher im \"Oberen Belvedere\" am 15. Mai 1955 unterzeichnet wurde)"}]'::jsonb, ''),
  ('schdootsvatrog', 'Schdootsvatrog', '', '', '', '', 'Staatsvertrag', '[{"kategorie": "kurz für", "text": "\"Österreichischer Staatsvertrag\" = \"internationaler Vertrag, der am 15. Mai 1955 in Wien im [[Schloss]] Belvedere unterzeichnet wurde und die zehnjährige [[Besatzungszeit]] Österreichs nach dem [[Zweiten]] Weltkrieg beendete\""}, {"kategorie": "", "text": "Die Unterzeichner waren die vier Besatzungsmächte (USA, Sowjetunion, Großbritannien und Frankreich) sowie die österreichische Regierung"}, {"kategorie": "", "text": "Der Vertrag stellte die volle Souveränität Österreichs wieder her und sah den Abzug aller ausländischen Truppen vor"}, {"kategorie": "", "text": "Gleichzeitig verpflichtete sich Österreich zur [[immerwährenden]] Neutralität, was bedeutete, dass es keine militärischen Bündnisse eingehen oder ausländische Militärbasen auf seinem Territorium zulassen würde"}, {"kategorie": "", "text": "Der Staatsvertrag sicherte zudem auch den Minderheitenschutz für slowenische und kroatische Bevölkerungsgruppen im südlichen Österreich zu"}, {"kategorie": "", "text": "Der Staatsvertrag war ein entscheidendes Dokument in der Nachkriegsordnung Europas und trug wesentlich dazu bei, Österreichs Position als neutraler Staat und Brücke zwischen Ost und West während des Kalten Krieges zu festigen."}]'::jsonb, ''),
  ('besotzungszeit', 'Besotzungszeit', '', '', '', '', 'Besatzungszeit', '[{"kategorie": "allg.", "text": "Zeitraum von 1945 bis 1955, als Österreich nach dem Ende des [[Zweiten]] Weltkriegs von den vier [[Alliierten]] (USA, Sowjetunion, Großbritannien und Frankreich) in vier [[Besatzungszonen]] aufgeteilt wurde"}, {"kategorie": "", "text": "Wien war ebenfalls in vier Sektoren aufgeteilt, wobei das Stadtzentrum von allen Mächten gemeinsam verwaltet wurde"}, {"kategorie": "", "text": "Während dieser Zeit stand Österreich unter der Kontrolle der [[Alliierten]], bis der [[österreichische]] Staatsvertrag 1955 die vollständige Souveränität des Landes wiederherstellte."}]'::jsonb, ''),
  ('nationalfeiatoog', 'Nationalfeiatoog', '', '', '', '', 'Nationalfeiertag', '[{"kategorie": "wörtlich", "text": "\"österreichischer Nationalfeiertag\" (wird seit 1965 jährlich begangen)"}, {"kategorie": "", "text": "Nationalfeiertag = 26. Oktober (erinnert an den Beschluss der [[immerwährenden]] Neutralität im Jahr 1955"}, {"kategorie": "", "text": "An diesem Tag beschloss der österreichische Nationalrat das [[Neutralitätsgesetz]], wodurch Österreich seine militärische Neutralität erklärte"}, {"kategorie": "", "text": "Der Feiertag symbolisiert die Unabhängigkeit und Souveränität des Landes nach dem Ende der alliierten Besatzung)"}]'::jsonb, ''),
  ('favoritaln', 'Favoritaln', '', '', '', '', 'Favoriterln', '[{"kategorie": "wörtlich", "text": "\"Damen-Schläfensträhnchen\"  (vom lateinischen \"favor\"=\"Wohlwollen\")"}, {"kategorie": "allg.", "text": "kleine, an den Schläfen heruntergekämmte Haarsträhnchen bei Frauen, \"Seitenfransen\", \"Seitensträhnchen\""}]'::jsonb, ''),
  ('faeae', 'Fää', '', '', '', '', 'Fee', '[{"kategorie": "wörtlich", "text": "\"Fee\" (vom französischen \"fée\"=\"Fee\")"}, {"kategorie": "allg.", "text": "Elfe, Märchengestalt, Märchenwesen"}]'::jsonb, ''),
  ('feiadoogsgwandl', 'Feiadoogsgwandl', '', '', '', '', 'Feiertagsgewand', '[{"kategorie": "wörtlich", "text": "\"das Gewand, das man nur an Feiertagen anzieht\" (vom mittelhochdeutschen \"vīretac\"=\"Feiertag\" und \"gewant\"=\"Gewand\")"}, {"kategorie": "", "text": "Festtagskleidung, Ausgehgewand, [[Sonntagsgewand]]"}]'::jsonb, ''),
  ('sundoogsgwandl', 'Sundoogsgwandl', '', '', '', '', 'Sonntagsgewand', '[{"kategorie": "wörtlich", "text": "\"das Gewand, das man nur an Sonntagen anzieht\" (vom mittelhochdeutschen \"sunnentac\"=\"Sonntag\" und \"gewant\"=\"Gewand\")"}, {"kategorie": "", "text": "Festtagskleidung, Ausgehgewand, [[Feiertagsgewand]]"}]'::jsonb, ''),
  ('feifoita', 'Feifoita', '', '', '', '', 'Feifalter', '[{"kategorie": "wörtlich", "text": "\"Kleiner Kohlweißling\" (lat. \"Pieris rapae\") bzw. \"Großer Kohlweißling\" (lat. \"Pieris brassicae\") (vom mittelhochdeutschen \"vīvalter\"=\"Schmetterling\")"}, {"kategorie": "allg.", "text": "Falter, Schmetterling"}]'::jsonb, ''),
  ('feinmechanika', 'Feinmechanika', '', '', '', '', 'Feinmechaniker', '[{"kategorie": "wörtlich, techn.", "text": "\"Präzisionsmechniker\" (\"Mechaniker, der beruflich feinmechanische elektrische, elektronische oder optische Gerätebzw. Bauteile herstellt und repariert\", Determinativkompositum aus \"fein\"=\"präzise\" und \"Mechaniker\"=\"Mikromechaniker\")"}, {"kategorie": "Fußballerjargon, scherzhaft für", "text": "Dribbelkünstler, Ballzauberer, Filigrantechniker"}]'::jsonb, ''),
  ('foeoesn', 'Föösn', '', '', '', 'Wiener Gaunersprache', 'Felsen', '[{"kategorie": "wörtlich", "text": "\"hartes Felsgestein\" (vom mittelhochdeutschen \"vels\"=\"Felsgestein\")"}, {"kategorie": "allg.", "text": "Granitfelsen, Felsblock, Felswand, Felsrücken, [[Flühe]]"}, {"kategorie": "Gaunersprache", "text": "Justizanstalt Stein an der Donau, Strafvollzugsanstalt Stein (in Anspielung darauf, dass sich eine von Österreichs größten Strafvollzugsanstalten auf Felsuntergrund in [[Stein]] an der Donau befindet)"}, {"kategorie": "Drogenjargon", "text": "\"Crack\" (kokainbasiertes Rauschmittel in fester Form), \"Crack-Stein\", \"Stone\", [[Schdaa]]"}]'::jsonb, 'Host an Föösn dabei?'),
  ('foeoesal', 'Föösal', '', '', '', '', 'Felserl', '[{"kategorie": "wörtlich", "text": "\"zufallendes Türschloss\" (vom mittelhochdeutschen \"fell-sloz\"=\"zufallendes Türschloss\")"}, {"kategorie": "Gaunersprache", "text": "Gefängniszelle, Haftzelle, Kerker"}, {"kategorie": "Verkleinerungsform von à\"Föösn\"", "text": "Justizanstalt Stein an der Donau, Strafvollzugsanstalt Stein (in Anspielung darauf, dass sich eine von Österreichs größten Strafvollzugsanstalten auf Felsuntergrund in [[Stein]] an der Donau befindet)"}]'::jsonb, ''),
  ('fenstaboikn', 'Fenstaboikn', '', '', '', '', 'Fensterbalken', '[{"kategorie": "wörtlich", "text": "\"Fensterladen\" (Determinativkompositum aus \"Fenster\"=\"Lichtöffnung\" und \"Balken\"=\"Fensterladen\")"}, {"kategorie": "allg.", "text": "[[Fensterladen]], Fensterklappe, Spalettladen"}]'::jsonb, ''),
  ('fenstabaunk', 'Fenstabaunk', '', '', '', '', 'Fensterbank', '[{"kategorie": "wörtlich", "text": "\"Sitzbank in einer Fensternische\" (Determinativkompositum aus \"Fenster\"=\"Lichtöffnung\" und \"Bank\"=\"Sitzbank\")"}, {"kategorie": "allg.", "text": "Fensterbrett, Fensterablage (horizontale Ablagefläche am unteren Rand eines Fensters)"}]'::jsonb, ''),
